function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function clean_key($v): string { return strtolower(preg_replace('/[^a-zA-Z0-9_]/','_',trim((string)$v))); }
function fmt_data($valor): string { if (!$valor) return '-'; try { return (new DateTime((string)$valor))->format('d/m/Y H:i'); } catch(Throwable $e){ return (string)$valor; } }
function mask_value($v, $type=''): string { $s=(string)$v; if($s==='') return ''; if($type==='cpf' || preg_match('/\d{3}\.?\d{3}\.?\d{3}-?\d{2}/',$s)) return substr($s,0,3).'.***.***-'.substr(preg_replace('/\D/','',$s),-2); if($type==='email' || str_contains($s,'@')){[$u,$d]=array_pad(explode('@',$s,2),2,''); return substr($u,0,2).'***@'.$d;} if($type==='phone' || strlen(preg_replace('/\D/','',$s))>=10) return '(**) *****-'.substr(preg_replace('/\D/','',$s),-4); return $s; }
function ensure_secure_storage(): void { global $STORAGE_DIR, $BACKUP_DIR; if(!is_dir($STORAGE_DIR)) @mkdir($STORAGE_DIR,0755,true); if(!is_dir($BACKUP_DIR)) @mkdir($BACKUP_DIR,0755,true); @file_put_contents($STORAGE_DIR.'/.htaccess', "Require all denied\nDeny from all\nOptions -Indexes\n<FilesMatch \"\\.(json|log|bak|zip)$\">\nRequire all denied\n</FilesMatch>\n", LOCK_EX); @file_put_contents($STORAGE_DIR.'/index.php', "<?php http_response_code(403); exit('Acesso negado.');"); @file_put_contents($STORAGE_DIR.'/web.config', "<?xml version=\"1.0\"?><configuration><system.webServer><security><requestFiltering><hiddenSegments><add segment=\"checksafe_storage\" /></hiddenSegments></requestFiltering></security></system.webServer></configuration>", LOCK_EX); @file_put_contents($BACKUP_DIR.'/.htaccess', "Require all denied\nDeny from all\nOptions -Indexes\n", LOCK_EX); @file_put_contents($BACKUP_DIR.'/index.php', "<?php http_response_code(403); exit('Acesso negado.');"); }
function read_json_file($path, $default=[]): array { if(!is_file($path)) return $default; $d=json_decode((string)@file_get_contents($path),true); return is_array($d)?$d:$default; }
function write_json_file($path, array $data): bool { ensure_secure_storage(); $json=json_encode($data, JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); return $json!==false && @file_put_contents($path,$json,LOCK_EX)!==false; }
function audit_log($acao, $detalhes=[]): void { global $AUDIT_FILE; $log=read_json_file($AUDIT_FILE,['eventos'=>[]]); $log['eventos'][]=['data'=>date('c'),'ip'=>$_SERVER['REMOTE_ADDR']??'','user_agent'=>substr($_SERVER['HTTP_USER_AGENT']??'',0,180),'acao'=>$acao,'detalhes'=>$detalhes]; if(count($log['eventos'])>800) $log['eventos']=array_slice($log['eventos'],-800); write_json_file($AUDIT_FILE,$log); }
function backup_file($path, $motivo='backup'): ?string { global $BACKUP_DIR; ensure_secure_storage(); if(!is_file($path)) return null; $name=date('Ymd_His').'_'.$motivo.'_'.basename($path); $dest=$BACKUP_DIR.'/'.$name; return @copy($path,$dest)?$dest:null; }
function backup_all($motivo='manual'): void { global $CONSULTAS_FILE; $settingsPath=function_exists('checksafe_settings_path')?checksafe_settings_path():null; backup_file($CONSULTAS_FILE,$motivo); if($settingsPath) backup_file($settingsPath,$motivo); audit_log('backup_criado',['motivo'=>$motivo]); }
function normalize_fields($raw): array { $fields=[]; foreach(($raw ?? []) as $f){ $name=clean_key($f['name']??''); if(!$name) continue; $fields[]=['name'=>$name,'label'=>trim((string)($f['label']??$name)),'type'=>trim((string)($f['type']??'text')),'placeholder'=>trim((string)($f['placeholder']??'')),'required'=>!empty($f['required']),'enabled'=>!empty($f['enabled'])]; } return $fields; }
function csv_download($rows, $name){ header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="'.$name.'"'); $out=fopen('php://output','w'); fputcsv($out,['CPF','Nome','E-mail','Telefone','Cidade','Tipo','Status','Ocorrências','Última consulta'],';'); foreach($rows as $r){$d=$r['dados_atuais']??[]; $res=$r['resultado_fixo']??[]; fputcsv($out,[$d['cpf']??$r['cpf']??'', $d['nome']??'', $d['email']??'', $d['telefone']??'', $d['cidade']??'', $d['origem_form']??$d['tipo_consulta']??'', $res['status']??'', $res['quantidade']??'', fmt_data($r['ultima_consulta']??'')],';');} exit; }
function json_download($data, $name){ header('Content-Type: application/json; charset=utf-8'); header('Content-Disposition: attachment; filename="'.$name.'"'); echo json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
