<?php if($tab==='consultas'): ?><section class="admin-card"><h2>Busca rápida</h2><p class="desc">Pesquise por CPF, telefone, e-mail, nome ou qualquer dado salvo da pesquisa.</p><form class="search-box" method="get"><input type="hidden" name="tab" value="consultas"><label>Buscar<input name="q" value="<?=h($q)?>" placeholder="Digite CPF, telefone, e-mail ou nome"></label><button class="btn-admin">Buscar</button><a class="btn-admin ghost" href="?tab=consultas">Limpar</a></form></section><section class="admin-card"><h2>Consultas encontradas: <?=count($filteredRows)?></h2><div class="table-list"><?php foreach(array_reverse($filteredRows) as $r): $d=$r['dados_atuais']??[]; $res=$r['resultado_fixo']??[];?><div class="row-card"><div class="row-head"><b><?=h($d['nome']??'Sem nome')?></b><small><?=fmt_data($r['ultima_consulta']??'')?></small></div><p><?=h($mask?mask_value($d['cpf']??$r['cpf']??'','cpf'):($d['cpf']??$r['cpf']??''))?> · <?=h($mask?mask_value($d['email']??'','email'):($d['email']??''))?> · <?=h($mask?mask_value($d['telefone']??'','phone'):($d['telefone']??''))?></p><div class="chips"><span><?=h($res['status']??'')?></span><span><?=h($res['quantidade']??0)?> ocorrência(s)</span><span><?=h($d['origem_form']??$d['tipo_consulta']??'')?></span></div><details class="consulta-details"><summary>👁️ Abrir informações completas da pesquisa</summary><div class="details-grid"><?php foreach($d as $dk=>$dv): ?><div class="detail-box"><b><?=h($dk)?></b><span><?=h(is_array($dv)?json_encode($dv,JSON_UNESCAPED_UNICODE):($mask?mask_value($dv,$dk):$dv))?></span></div><?php endforeach; ?><div class="detail-box"><b>Status</b><span><?=h($res['status']??'')?></span></div><div class="detail-box"><b>Ocorrências</b><span><?=h($res['quantidade']??0)?></span></div><?php if(!empty($res['empresas']) && is_array($res['empresas'])): ?><div class="detail-box adm-full"><b>Empresas exibidas</b><p><?php foreach($res['empresas'] as $emp): ?>• <?=h($emp['nome']??'')?> <?=!empty($emp['tipo'])?'('.h($emp['tipo']).')':''?><br><?php endforeach; ?></p></div><?php endif; ?><pre class="json-mini"><?=h(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre></div></details></div><?php endforeach; if(!count($filteredRows)):?><p class="muted">Nenhuma consulta encontrada.</p><?php endif;?></div></section><?php endif; ?>
<?php if($tab==='empresas'): ?><section class="admin-card"><h2>Adicionar empresa</h2><p class="desc">Cadastre empresas que podem aparecer nos resultados.</p><form method="post" class="adm-grid"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="empresa_add"><label>Nome<input name="nome" required></label><label>Categoria/tipo<input name="tipo" placeholder="Marketplace, Banco, App..."></label><label>Data<input name="data" placeholder="Jan 2026"></label><label>Status<select name="status"><option value="vazada">Dados comprometidos</option><option value="segura">Dados seguros</option></select></label><label class="adm-full">Descrição<textarea name="texto" rows="3"></textarea></label><label class="adm-full">Dados envolvidos, separados por vírgula<input name="dados" placeholder="Nome, CPF, E-mail"></label><button class="btn-admin adm-full">Adicionar empresa</button></form></section><section class="admin-card"><h2>Empresas cadastradas</h2><div class="table-list"><?php foreach(($settings['empresas']??[]) as $i=>$e):?><div class="row-card"><form method="post" class="adm-grid"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="empresa_edit"><input type="hidden" name="i" value="<?=$i?>"><label>Nome<input name="nome" value="<?=h($e['nome']??'')?>"></label><label>Tipo<input name="tipo" value="<?=h($e['tipo']??'')?>"></label><label>Data<input name="data" value="<?=h($e['data']??'')?>"></label><label>Status<select name="status"><option value="vazada" <?=($e['status']??'vazada')==='vazada'?'selected':''?>>Comprometida</option><option value="segura" <?=($e['status']??'')==='segura'?'selected':''?>>Segura</option></select></label><label class="adm-full">Texto<textarea name="texto" rows="2"><?=h($e['texto']??'')?></textarea></label><label class="adm-full">Dados<input name="dados" value="<?=h(implode(', ', $e['dados']??[]))?>"></label><button class="btn-admin">Salvar</button></form><form method="post" onsubmit="return confirm('Remover empresa?')"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="empresa_del"><input type="hidden" name="i" value="<?=$i?>"><button class="btn-admin danger">Remover</button></form></div><?php endforeach;?></div></section><?php endif; ?>
<?php if($tab==='formularios'): $fc=$settings['forms'][$formTab]??$settings['form']; ?><section class="admin-card"><h2>Formulários</h2><p class="desc">Cada card possui texto e campos independentes.</p><div class="form-tabs"><a class="form-tab <?=$formTab==='dados01'?'active':''?>" href="?tab=formularios&form=dados01"><strong>Dados pessoas 01</strong><span>Formulário principal</span></a><a class="form-tab <?=$formTab==='dados02'?'active':''?>" href="?tab=formularios&form=dados02"><strong>Dados pessoas 02</strong><span>Formulário complementar</span></a></div><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="form_save"><input type="hidden" name="form_id" value="<?=$formTab?>"><div class="adm-grid" style="margin-top:16px"><label>Título<input name="title" value="<?=h($fc['title']??'')?>"></label><label>Botão<input name="button" value="<?=h($fc['button']??'')?>"></label><label class="adm-full">Subtítulo<textarea name="subtitle" rows="2"><?=h($fc['subtitle']??'')?></textarea></label></div><h2 style="margin-top:24px">Campos</h2><?php foreach(($fc['fields']??[]) as $i=>$f):?><div class="field-line"><label>Nome interno<input name="fields[<?=$i?>][name]" value="<?=h($f['name']??'')?>"></label><label>Título<input name="fields[<?=$i?>][label]" value="<?=h($f['label']??'')?>"></label><label>Tipo<select name="fields[<?=$i?>][type]"><?php foreach(['text'=>'Texto','cpf'=>'CPF','email'=>'E-mail','phone'=>'Telefone','number'=>'Número','date'=>'Data'] as $v=>$l):?><option value="<?=$v?>" <?=($f['type']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Placeholder<input name="fields[<?=$i?>][placeholder]" value="<?=h($f['placeholder']??'')?>"></label><label class="check-pill"><input type="checkbox" name="fields[<?=$i?>][required]" <?=!empty($f['required'])?'checked':''?>>Obrig.</label><label class="check-pill"><input type="checkbox" name="fields[<?=$i?>][enabled]" <?=!empty($f['enabled'])?'checked':''?>>Ativo</label></div><?php endforeach;?><button class="btn-admin">Salvar formulário</button></form></section><?php endif; ?>
<?php if($tab==='seguranca'): ?><section class="admin-card"><h2>Segurança</h2><p class="desc">Proteções do painel, arquivos JSON, backups e logs de alterações.</p><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="security"><div class="security-grid"><?php foreach(['mask_admin'=>'Mascarar dados sensíveis no painel','save_full_data'=>'Salvar dados completos no JSON protegido','block_json'=>'Bloquear acesso direto ao storage','backup_on_save'=>'Backup automático antes de salvar','login_lock'=>'Bloquear login após tentativas erradas','audit_log'=>'Registrar alterações do administrador'] as $k=>$label):?><label class="security-item"><span><b><?=h($label)?></b><small>Recomendado manter ativo em produção.</small></span><span class="switch"><input type="checkbox" name="<?=$k?>" <?=!empty($sec[$k])?'checked':''?>><span class="toggle"></span></span></label><?php endforeach;?></div><button class="btn-admin adm-full" style="margin-top:16px;width:100%">Salvar segurança</button></form></section><section class="admin-card"><h2>Status dos arquivos</h2><p class="desc">Storage: <b><?=h($STORAGE_DIR)?></b></p><div class="file-status-grid"><span>JSON consultas<br><?=is_file($CONSULTAS_FILE)?'OK':'não criado'?></span><span>.htaccess<br><?=is_file($STORAGE_DIR.'/.htaccess')?'OK':'ausente'?></span><span>Backups<br><?=is_dir($BACKUP_DIR)?'OK':'ausente'?></span></div><form method="post" class="report-actions" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="manual_backup"><button class="btn-admin">Criar backup agora</button><a class="btn-admin ghost" href="?tab=seguranca&export=audit">Baixar logs</a></form></section><section class="admin-card"><h2>Logs de alterações</h2><div class="audit-list"><?php foreach(array_reverse(array_slice($audit['eventos']??[],-30)) as $ev):?><div class="audit-item"><b><?=fmt_data($ev['data']??'')?></b><span><?=h($ev['acao']??'')?></span><small><?=h($ev['ip']??'')?></small></div><?php endforeach; if(empty($audit['eventos'])):?><p class="muted">Nenhum log registrado ainda.</p><?php endif;?></div><form method="post" onsubmit="return confirm('Limpar logs de alterações?')" style="margin-top:14px"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="clear_audit"><button class="btn-admin danger">Limpar logs</button></form></section><?php endif; ?>
<?php if($tab==='relatorios'): ?><section class="admin-card"><h2>Relatórios</h2><p class="desc">Exporte dados e acompanhe as consultas salvas.</p><div class="report-actions"><a class="btn-admin" href="?tab=relatorios&export=csv">Exportar CSV</a><a class="btn-admin ghost" href="?tab=relatorios&export=json">Exportar JSON</a><a class="btn-admin ghost" href="?tab=consultas">Busca rápida</a></div><form method="post" onsubmit="return confirm('Apagar todas as consultas salvas?')" style="margin-top:14px"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="clear_logs"><button class="btn-admin danger">Limpar consultas</button></form></section><section class="admin-card"><h2>Resumo</h2><div class="kpis"><div class="metric"><strong><?=$totalCpfs?></strong><span>Registros</span></div><div class="metric"><strong><?=$comp?></strong><span>Comprometidos</span></div><div class="metric"><strong><?=$seg?></strong><span>Seguros</span></div><div class="metric"><strong><?=$today?></strong><span>Hoje</span></div><div class="metric"><strong><?=$month?></strong><span>Mês</span></div></div></section><?php endif; ?>
<?php if($tab==='manutencao'): $m=$settings['maintenance']??[]; ?><section class="admin-card"><h2>Modo manutenção</h2><p class="desc">Ative uma página bonita de aviso sem apagar o site.</p><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="acao" value="maintenance"><label class="security-item"><span><b><?=!empty($m['active'])?'Manutenção ativa':'Site online'?></b><small>Quando ativo, visitantes veem a mensagem de manutenção.</small></span><span class="switch"><input type="checkbox" name="active" <?=!empty($m['active'])?'checked':''?>><span class="toggle"></span></span></label><div class="adm-grid" style="margin-top:16px"><label>Título<input name="title" value="<?=h($m['title']??'Site em manutenção')?>"></label><label>Contato opcional<input name="contact" value="<?=h($m['contact']??'')?>"></label><label class="adm-full">Mensagem<textarea name="message" rows="4"><?=h($m['message']??'Estamos fazendo ajustes.')?></textarea></label></div><button class="btn-admin" style="margin-top:16px">Salvar manutenção</button></form></section><section class="admin-card"><h2>Preview</h2><div class="preview-box"><h3><?=h($m['title']??'Site em manutenção')?></h3><p><?=nl2br(h($m['message']??'Estamos fazendo ajustes.'))?></p><?php if(!empty($m['contact'])):?><div class="chips" style="justify-content:center"><span><?=h($m['contact'])?></span></div><?php endif;?></div></section><?php endif; ?>
